const e={title_add:"Add a CLI of your own",title_edit:"Edit this CLI",description:"Any interactive terminal CLI can run in a pane here. Give it a name and the command that starts it, and it appears everywhere the built-in ones do.",close:"Close",cancel:"Cancel",save:"Save",save_add:"Add CLI",saving:"Saving…",name:"Name",name_placeholder:"e.g. Aider",name_hint:"What you will see in the pickers and say out loud.",command:"Command",command_placeholder:"aider",command_hint:"Exactly what you would type in a terminal to start it.",command_shell_hint:"This runs through a shell, because the command is more than one program. The pane closes when the whole line is done.",description_label:"Description",optional:"Optional",description_placeholder:"One line explaining what this CLI is.",at_reference:"Write dropped files as @path",at_reference_hint:"Most modern coding CLIs read @path as a file to open. Leave this off and paths are pasted in quotes instead.",threads_title:"Run in threads (optional)",headless_command:"Headless command",headless_command_hint:"Lets this CLI also appear as a provider in Agentic IDE threads. Use {prompt} where the message goes; leave it out and the message is sent on stdin. The answer is whatever the command prints.",headless_resume:"Resume command",headless_resume_hint:"Used for follow-up turns. {session} is replaced by the conversation id. Leave empty to start fresh each turn.",pick_logo:"Choose a logo",remove_logo:"Remove the logo",remove_logo_short:"Remove",logo_label:"Logo"},a={custom_cli:e};export{e as custom_cli,a as default};
